<script setup lang="ts">
import { reactive,ref } from 'vue'
import { NModal,NCard,NForm,NFormItem,NInput,NButton,NAlert,useMessage,useDialog } from 'naive-ui'
import { api,errorText,lines,splitLines,type Platform } from '../api'
defineProps<{show:boolean;items:Platform[]}>();const emit=defineEmits<{'update:show':[boolean];changed:[]}>()
const msg=useMessage(),dialog=useDialog(),editing=ref(false),busy=ref(false),form=reactive({id:'',name:'',emails:'',domains:'',keywords:''})
function edit(p?:Platform){Object.assign(form,{id:p?.id||'',name:p?.name||'',emails:splitLines(p?.sender_emails),domains:splitLines(p?.sender_domains),keywords:splitLines(p?.subject_keywords)});editing.value=true}
async function save(){busy.value=true;try{await api('admin/platforms','POST',{id:form.id,name:form.name,sender_emails:lines(form.emails),sender_domains:lines(form.domains),subject_keywords:lines(form.keywords)});emit('changed');editing.value=false;msg.success('平台规则已保存')}catch(e){msg.error(errorText(e))}finally{busy.value=false}}
function remove(p:Platform){dialog.warning({title:'删除平台规则',content:`删除“${p.name}”？请先解除访问链接对它的绑定。`,positiveText:'删除',negativeText:'取消',onPositiveClick:async()=>{try{await api('admin/platforms/'+p.id,'DELETE');emit('changed')}catch(e){msg.error(errorText(e))}}})}
</script>
<template><NModal :show="show" @update:show="v=>emit('update:show',v)"><NCard class="form-modal" title="平台规则" closable @close="emit('update:show',false)"><NAlert type="info" :show-icon="false">匹配发件邮箱或域名（含子域名）。设置主题关键词后，还需命中任一关键词。收件人始终固定为链接绑定地址。</NAlert><NForm v-if="editing" @submit.prevent="save"><NFormItem label="平台名称"><NInput v-model:value="form.name" placeholder="例如：GitHub" /></NFormItem><NFormItem label="发件邮箱（每行一个）"><NInput v-model:value="form.emails" type="textarea" :rows="3" placeholder="noreply@example.com" /></NFormItem><NFormItem label="发件域名（每行一个）"><NInput v-model:value="form.domains" type="textarea" :rows="3" placeholder="example.com" /></NFormItem><NFormItem label="主题关键词（选填，每行一个）"><NInput v-model:value="form.keywords" type="textarea" :rows="3" placeholder="验证码&#10;verification" /></NFormItem><div class="form-actions"><NButton @click="editing=false">返回列表</NButton><NButton type="primary" attr-type="submit" :loading="busy">保存规则</NButton></div></NForm><template v-else><div v-for="p in items" :key="p.id" class="editor-row"><div><strong>{{ p.name }}</strong><div class="subline">{{ p.sender_emails.length }} 个地址 · {{ p.sender_domains.length }} 个域名</div></div><div class="row"><NButton quaternary @click="edit(p)">编辑</NButton><NButton quaternary type="error" @click="remove(p)">删除</NButton></div></div><p v-if="!items.length" class="empty">还没有平台规则</p><div class="form-actions"><NButton type="primary" @click="edit()">新增平台</NButton></div></template></NCard></NModal></template>
